{"filePath":"/root/work/gles-bridge-mod/src/main/java/net/glesbridge/GLESBridgeMod.java","content":"package net.glesbridge;

import net.fabricmc.api.ClientModInitializer;
import org.lwjgl.gles.GLES30;
import org.lwjgl.gles.GLES31;
import org.lwjgl.gles.GLES32;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class GLESBridgeMod implements ClientModInitializer {
    public static final String MOD_ID = "gles-bridge-mod";
    public static final Logger LOGGER = LoggerFactory.getLogger(MOD_ID);

    @Override
    public void onInitializeClient() {
        LOGGER.info("[GLES Bridge] Initializing - OpenGL ES 3.x native bridge active");

        // Verify GLES bindings are available
        if (GLES30.glGetString(GLES30.GL_VERSION) != null) {
            String version = GLES30.glGetString(GLES30.GL_VERSION);
            String renderer = GLES30.glGetString(GLES30.GL_RENDERER);
            LOGGER.info("[GLES Bridge] GLES Version: {}", version);
            LOGGER.info("[GLES Bridge] GLES Renderer: {}", renderer);
        } else {
            LOGGER.warn("[GLES Bridge] GLES bindings not available - falling back to GL");
        }

        // Register GLES state tracker
        GLESStateTracker.init();

        // Shader compiler bridge
        GLESShaderBridge.init();

        LOGGER.info("[GLES Bridge] Initialization complete - no translation layer loaded");
    }
}"}

{"content":"package net.glesbridge;

import org.lwjgl.gles.GLES30;
import org.lwjgl.gles.GLES31;
import org.lwjgl.gles.GLES32;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class GLESStateTracker {
    private static final Logger LOGGER = LoggerFactory.getLogger("GLES Bridge/State");

    // Track current GLES state to avoid redundant calls
    private static int activeTexture = GLES30.GL_TEXTURE0;
    private static int boundTexture2D = 0;
    private static int boundBufferArray = 0;
    private static int boundBufferElement = 0;
    private static int boundVertexArray = 0;
    private static int currentProgram = 0;

    // Blend state
    private static boolean blendEnabled = false;
    private static int blendSrcRGB = GLES30.GL_ONE;
    private static int blendDstRGB = GLES30.GL_ZERO;
    private static int blendSrcAlpha = GLES30.GL_ONE;
    private static int blendDstAlpha = GLES30.GL_ZERO;

    // Depth state
    private static boolean depthTestEnabled = false;
    private static int depthFunc = GLES30.GL_LESS;
    private static boolean depthMask = true;

    // Cull state
    private static boolean cullEnabled = false;
    private static int cullFace = GLES30.GL_BACK;
    private static int frontFace = GLES30.GL_CCW;

    // Stencil state
    private static boolean stencilEnabled = false;

    // Scissor state
    private static boolean scissorEnabled = false;

    // Viewport
    private static int viewportX = 0, viewportY = 0, viewportW = 0, viewportH = 0;

    private GLESStateTracker() {}

    public static void init() {
        LOGGER.info("GLES State Tracker initialized");
    }

    // Texture binding
    public static void activeTexture(int texture) {
        if (activeTexture != texture) {
            GLES30.glActiveTexture(texture);
            activeTexture = texture;
        }
    }

    public static void bindTexture2D(int texture) {
        if (boundTexture2D != texture) {
            GLES30.glBindTexture(GLES30.GL_TEXTURE_2D, texture);
            boundTexture2D = texture;
        }
    }

    public static void bindBuffer(int target, int buffer) {
        if (target == GLES30.GL_ARRAY_BUFFER) {
            if (boundBufferArray != buffer) {
                GLES30.glBindBuffer(target, buffer);
                boundBufferArray = buffer;
            }
        } else if (target == GLES30.GL_ELEMENT_ARRAY_BUFFER) {
            if (boundBufferElement != buffer) {
                GLES30.glBindBuffer(target, buffer);
                boundBufferElement = buffer;
            }
        } else {
            GLES30.glBindBuffer(target, buffer);
        }
    }

    public static void bindVertexArray(int vao) {
        if (boundVertexArray != vao) {
            GLES30.glBindVertexArray(vao);
            boundVertexArray = vao;
        }
    }

    public static void useProgram(int program) {
        if (currentProgram != program) {
            GLES30.glUseProgram(program);
            currentProgram = program;
        }
    }

    // Blend
    public static void setBlend(boolean enabled) {
        if (blendEnabled != enabled) {
            if (enabled) GLES30.glEnable(GLES30.GL_BLEND);
            else GLES30.glDisable(GLES30.GL_BLEND);
            blendEnabled = enabled;
        }
    }

    public static void setBlendFuncSeparate(int srcRGB, int dstRGB, int srcAlpha, int dstAlpha) {
        if (blendSrcRGB != srcRGB || blendDstRGB != dstRGB || blendSrcAlpha != srcAlpha || blendDstAlpha != dstAlpha) {
            GLES30.glBlendFuncSeparate(srcRGB, dstRGB, srcAlpha, dstAlpha);
            blendSrcRGB = srcRGB;
            blendDstRGB = dstRGB;
            blendSrcAlpha = srcAlpha;
            blendDstAlpha = dstAlpha;
        }
    }

    // Depth
    public static void setDepthTest(boolean enabled) {
        if (depthTestEnabled != enabled) {
            if (enabled) GLES30.glEnable(GLES30.GL_DEPTH_TEST);
            else GLES30.glDisable(GLES30.GL_DEPTH_TEST);
            depthTestEnabled = enabled;
        }
    }

    public static void setDepthFunc(int func) {
        if (depthFunc != func) {
            GLES30.glDepthFunc(func);
            depthFunc = func;
        }
    }

    public static void setDepthMask(boolean mask) {
        if (depthMask != mask) {
            GLES30.glDepthMask(mask);
            depthMask = mask;
        }
    }

    // Cull
    public static void setCullFace(boolean enabled) {
        if (cullEnabled != enabled) {
            if (enabled) GLES30.glEnable(GLES30.GL_CULL_FACE);
            else GLES30.glDisable(GLES30.GL_CULL_FACE);
            cullEnabled = enabled;
        }
    }

    public static void setCullFaceMode(int mode) {
        if (cullFace != mode) {
            GLES30.glCullFace(mode);
            cullFace = mode;
        }
    }

    public static void setFrontFace(int mode) {
        if (frontFace != mode) {
            GLES30.glFrontFace(mode);
            frontFace = mode;
        }
    }

    // Stencil
    public static void setStencilTest(boolean enabled) {
        if (stencilEnabled != enabled) {
            if (enabled) GLES30.glEnable(GLES30.GL_STENCIL_TEST);
            else GLES30.glDisable(GLES30.GL_STENCIL_TEST);
            stencilEnabled = enabled;
        }
    }

    // Scissor
    public static void setScissorTest(boolean enabled) {
        if (scissorEnabled != enabled) {
            if (enabled) GLES30.glEnable(GLES30.GL_SCISSOR_TEST);
            else GLES30.glDisable(GLES30.GL_SCISSOR_TEST);
            scissorEnabled = enabled;
        }
    }

    public static void setScissor(int x, int y, int w, int h) {
        GLES30.glScissor(x, y, w, h);
    }

    // Viewport
    public static void setViewport(int x, int y, int w, int h) {
        if (viewportX != x || viewportY != y || viewportW != w || viewportH != h) {
            GLES30.glViewport(x, y, w, h);
            viewportX = x; viewportY = y; viewportW = w; viewportH = h;
        }
    }

    // Clear
    public static void clear(int mask, float r, float g, float b, float a) {
        GLES30.glClearColor(r, g, b, a);
        GLES30.glClear(mask);
    }

    // Draw
    public static void drawArrays(int mode, int first, int count) {
        GLES30.glDrawArrays(mode, first, count);
    }

    public static void drawElements(int mode, int count, int type, long indicesOffset) {
        GLES30.glDrawElements(mode, count, type, indicesOffset);
    }

    public static void drawElementsInstanced(int mode, int count, int type, long indicesOffset, int instanceCount) {
        GLES31.glDrawElementsInstanced(mode, count, type, indicesOffset, instanceCount);
    }

    // Getters for state inspection
    public static int getActiveTexture() { return activeTexture; }
    public static int getBoundTexture2D() { return boundTexture2D; }
    public static int getCurrentProgram() { return currentProgram; }
    public static boolean isBlendEnabled() { return blendEnabled; }
    public static boolean isDepthTestEnabled() { return depthTestEnabled; }
    public static boolean isCullEnabled() { return cullEnabled; }
    public static boolean isStencilEnabled() { return stencilEnabled; }
    public static boolean isScissorEnabled() { return scissorEnabled; }
}"}

