{"content":"package net.glesbridge;

import org.lwjgl.gles.GLES30;
import org.lwjgl.gles.GLES31;
import org.lwjgl.gles.GLES32;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.nio.IntBuffer;
import java.util.HashMap;
import java.util.Map;

public class GLESShaderBridge {
    private static final Logger LOGGER = LoggerFactory.getLogger("GLES Bridge/Shader");

    // Track shader programs
    private static final Map<Integer, ShaderProgram> programs = new HashMap<>();
    private static int currentProgram = 0;

    public static class ShaderProgram {
        public final int id;
        public final Map<String, Integer> uniforms = new HashMap<>();
        public final Map<String, Integer> attributes = new HashMap<>();

        public ShaderProgram(int id) {
            this.id = id;
        }
    }

    public static void init() {
        LOGGER.info("GLES Shader Bridge initialized");
    }

    public static int createProgram() {
        int program = GLES30.glCreateProgram();
        programs.put(program, new ShaderProgram(program));
        return program;
    }

    public static void deleteProgram(int program) {
        ShaderProgram sp = programs.remove(program);
        if (sp != null) {
            GLES30.glDeleteProgram(program);
        }
    }

    public static int createShader(int type) {
        // Map GL types to GLES
        int glesType = mapShaderType(type);
        return GLES30.glCreateShader(glesType);
    }

    private static int mapShaderType(int type) {
        return switch (type) {
            case 0x8B31 -> GLES30.GL_VERTEX_SHADER;        // GL_VERTEX_SHADER
            case 0x8B30 -> GLES30.GL_FRAGMENT_SHADER;      // GL_FRAGMENT_SHADER
            case 0x8DD9 -> GLES31.GL_GEOMETRY_SHADER;      // GL_GEOMETRY_SHADER (GLES 3.1+)
            case 0x8E87 -> GLES31.GL_TESS_CONTROL_SHADER;  // GL_TESS_CONTROL_SHADER (GLES 3.1+)
            case 0x8E88 -> GLES31.GL_TESS_EVALUATION_SHADER; // GL_TESS_EVALUATION_SHADER (GLES 3.1+)
            case 0x91B9 -> GLES31.GL_COMPUTE_SHADER;       // GL_COMPUTE_SHADER (GLES 3.1+)
            default -> type;
        };
    }

    public static void shaderSource(int shader, String source) {
        // Convert GLSL desktop to GLSL ES if needed
        String esSource = convertGLSLtoESSL(source);
        GLES30.glShaderSource(shader, esSource);
    }

    private static String convertGLSLtoESSL(String source) {
        // Basic conversions from desktop GLSL to GLSL ES
        String result = source;

        // Version directive - ensure ES 3.0+
        if (!result.contains("#version")) {
            result = "#version 300 es\n" + result;
        } else {
            // Replace desktop version with ES version
            result = result.replaceAll("#version\\s+\\d+", "#version 300 es");
        }

        // Precision qualifiers for fragment shader
        if (result.contains("GL_FRAGMENT_SHADER") || result.contains("fragment")) {
            if (!result.contains("precision highp float")) {
                result = result.replaceFirst("#version 300 es", "#version 300 es\nprecision highp float;\nprecision highp int;");
            }
        }

        // Replace deprecated built-ins
        result = result
            .replace("gl_FragColor", "fragColor")
            .replace("gl_FragData", "fragData")
            .replace("texture2D(", "texture(")
            .replace("textureCube(", "texture(")
            .replace("texture2DProj(", "textureProj(")
            .replace("textureCubeLod(", "textureLod(");

        // Attribute/in/out qualifiers
        result = result
            .replace("attribute ", "in ")
            .replace("varying ", "out ")
            .replace("attribute", "in")
            .replace("varying", "out");

        return result;
    }

    public static void compileShader(int shader) {
        GLES30.glCompileShader(shader);

        int[] compiled = new int[1];
        GLES30.glGetShaderiv(shader, GLES30.GL_COMPILE_STATUS, compiled, 0);
        if (compiled[0] == 0) {
            String log = GLES30.glGetShaderInfoLog(shader);
            LOGGER.error("Shader compilation failed: {}", log);
            throw new RuntimeException("Shader compilation failed: " + log);
        }
    }

    public static void attachShader(int program, int shader) {
        GLES30.glAttachShader(program, shader);
    }

    public static void linkProgram(int program) {
        GLES30.glLinkProgram(program);

        int[] linked = new int[1];
        GLES30.glGetProgramiv(program, GLES30.GL_LINK_STATUS, linked, 0);
        if (linked[0] == 0) {
            String log = GLES30.glGetProgramInfoLog(program);
            LOGGER.error("Program linking failed: {}", log);
            throw new RuntimeException("Program linking failed: " + log);
        }
    }

    public static void useProgram(int program) {
        if (currentProgram != program) {
            GLES30.glUseProgram(program);
            currentProgram = program;
        }
    }

    public static int getUniformLocation(int program, String name) {
        ShaderProgram sp = programs.get(program);
        if (sp != null) {
            Integer cached = sp.uniforms.get(name);
            if (cached != null) return cached;
            int loc = GLES30.glGetUniformLocation(program, name);
            sp.uniforms.put(name, loc);
            return loc;
        }
        return GLES30.glGetUniformLocation(program, name);
    }

    public static int getAttribLocation(int program, String name) {
        ShaderProgram sp = programs.get(program);
        if (sp != null) {
            Integer cached = sp.attributes.get(name);
            if (cached != null) return cached;
            int loc = GLES30.glGetAttribLocation(program, name);
            sp.attributes.put(name, loc);
            return loc;
        }
        return GLES30.glGetAttribLocation(program, name);
    }

    // Uniform setters
    public static void uniform1i(int location, int value) {
        if (location >= 0) GLES30.glUniform1i(location, value);
    }

    public static void uniform1f(int location, float value) {
        if (location >= 0) GLES30.glUniform1f(location, value);
    }

    public static void uniform2f(int location, float x, float y) {
        if (location >= 0) GLES30.glUniform2f(location, x, y);
    }

    public static void uniform3f(int location, float x, float y, float z) {
        if (location >= 0) GLES30.glUniform3f(location, x, y, z);
    }

    public static void uniform4f(int location, float x, float y, float z, float w) {
        if (location >= 0) GLES30.glUniform4f(location, x, y, z, w);
    }

    public static void uniformMatrix4fv(int location, boolean transpose, float[] matrix, int offset) {
        if (location >= 0) GLES30.glUniformMatrix4fv(location, 1, transpose, matrix, offset);
    }

    public static int getCurrentProgram() {
        return currentProgram;
    }
}","filePath":"/root/work/gles-bridge-mod/src/main/java/net/glesbridge/GLESShaderBridge.java"}

{"content":"package net.glesbridge.mixin;

import com.mojang.blaze3d.opengl.GlStateManager;
import com.mojang.blaze3d.systems.RenderSystem;
import net.glesbridge.GLESStateTracker;
import net.glesbridge.GLESShaderBridge;
import org.lwjgl.gles.GLES30;
import org.spongepowered.asm.mixin.Mixin;
import org.spongepowered.asm.mixin.injection.At;
import org.spongepowered.asm.mixin.injection.Inject;
import org.spongepowered.asm.mixin.injection.callback.CallbackInfo;
import org.spongepowered.asm.mixin.injection.callback.CallbackInfoReturnable;

@Mixin(GlStateManager.class)
public class GlStateManagerMixin {

    // Enable/disable cap
    @Inject(method = "enable", at = @At("HEAD"), cancellable = true)
    private static void onEnable(int cap, CallbackInfo ci) {
        int glesCap = mapCap(cap);
        if (glesCap >= 0) {
            GLES30.glEnable(glesCap);
            ci.cancel();
        }
    }

    @Inject(method = "disable", at = @At("HEAD"), cancellable = true)
    private static void onDisable(int cap, CallbackInfo ci) {
        int glesCap = mapCap(cap);
        if (glesCap >= 0) {
            GLES30.glDisable(glesCap);
            ci.cancel();
        }
    }

    // Blend
    @Inject(method = "blendFuncSeparate", at = @At("HEAD"), cancellable = true)
    private static void onBlendFuncSeparate(int srcRGB, int dstRGB, int srcAlpha, int dstAlpha, CallbackInfo ci) {
        GLESStateTracker.setBlendFuncSeparate(mapBlendFactor(srcRGB), mapBlendFactor(dstRGB), 
                                              mapBlendFactor(srcAlpha), mapBlendFactor(dstAlpha));
        ci.cancel();
    }

    @Inject(method = "blendFunc", at = @At("HEAD"), cancellable = true)
    private static void onBlendFunc(int src, int dst, CallbackInfo ci) {
        GLESStateTracker.setBlendFuncSeparate(mapBlendFactor(src), mapBlendFactor(dst),
                                              mapBlendFactor(src), mapBlendFactor(dst));
        ci.cancel();
    }

    // Depth
    @Inject(method = "depthFunc", at = @At("HEAD"), cancellable = true)
    private static void onDepthFunc(int func, CallbackInfo ci) {
        GLESStateTracker.setDepthFunc(mapDepthFunc(func));
        ci.cancel();
    }

    @Inject(method = "depthMask", at = @At("HEAD"), cancellable = true)
    private static void onDepthMask(boolean flag, CallbackInfo ci) {
        GLESStateTracker.setDepthMask(flag);
        ci.cancel();
    }

    // Cull
    @Inject(method = "cullFace", at = @At("HEAD"), cancellable = true)
    private static void onCullFace(int mode, CallbackInfo ci) {
        GLESStateTracker.setCullFaceMode(mapCullFace(mode));
        ci.cancel();
    }

    @Inject(method = "enableCull", at = @At("HEAD"), cancellable = true)
    private static void onEnableCull(CallbackInfo ci) {
        GLESStateTracker.setCullFace(true);
        ci.cancel();
    }

    @Inject(method = "disableCull", at = @At("HEAD"), cancellable = true)
    private static void onDisableCull(CallbackInfo ci) {
        GLESStateTracker.setCullFace(false);
        ci.cancel();
    }

    // Polygon offset
    @Inject(method = "polygonOffset", at = @At("HEAD"), cancellable = true)
    private static void onPolygonOffset(float factor, float units, CallbackInfo ci) {
        GLES30.glPolygonOffset(factor, units);
        ci.cancel();
    }

    // Line width
    @Inject(method = "lineWidth", at = @At("HEAD"), cancellable = true)
    private static void onLineWidth(float width, CallbackInfo ci) {
        GLES30.glLineWidth(width);
        ci.cancel();
    }

    // Viewport
    @Inject(method = "viewport", at = @At("HEAD"), cancellable = true)
    private static void onViewport(int x, int y, int width, int height, CallbackInfo ci) {
        GLESStateTracker.setViewport(x, y, width, height);
        ci.cancel();
    }

    // Scissor
    @Inject(method = "scissor", at = @At("HEAD"), cancellable = true)
    private static void onScissor(int x, int y, int width, int height, CallbackInfo ci) {
        GLESStateTracker.setScissor(x, y, width, height);
        ci.cancel();
    }

    @Inject(method = "enableScissor", at = @At("HEAD"), cancellable = true)
    private static void onEnableScissor(CallbackInfo ci) {
        GLESStateTracker.setScissorTest(true);
        ci.cancel();
    }

    @Inject(method = "disableScissor", at = @At("HEAD"), cancellable = true)
    private static void onDisableScissor(CallbackInfo ci) {
        GLESStateTracker.setScissorTest(false);
        ci.cancel();
    }

    // Stencil
    @Inject(method = "stencilFunc", at = @At("HEAD"), cancellable = true)
    private static void onStencilFunc(int func, int ref, int mask, CallbackInfo ci) {
        GLES30.glStencilFunc(mapStencilFunc(func), ref, mask);
        ci.cancel();
    }

    @Inject(method = "stencilOp", at = @At("HEAD"), cancellable = true)
    private static void onStencilOp(int fail, int zfail, int zpass, CallbackInfo ci) {
        GLES30.glStencilOp(mapStencilOp(fail), mapStencilOp(zfail), mapStencilOp(zpass));
        ci.cancel();
    }

    @Inject(method = "stencilMask", at = @At("HEAD"), cancellable = true)
    private static void onStencilMask(int mask, CallbackInfo ci) {
        GLES30.glStencilMask(mask);
        ci.cancel();
    }

    @Inject(method = "enableStencil", at = @At("HEAD"), cancellable = true)
    private static void onEnableStencil(CallbackInfo ci) {
        GLESStateTracker.setStencilTest(true);
        ci.cancel();
    }

    @Inject(method = "disableStencil", at = @At("HEAD"), cancellable = true)
    private static void onDisableStencil(CallbackInfo ci) {
        GLESStateTracker.setStencilTest(false);
        ci.cancel();
    }

    // Color mask
    @Inject(method = "colorMask", at = @At("HEAD"), cancellable = true)
    private static void onColorMask(boolean red, boolean green, boolean blue, boolean alpha, CallbackInfo ci) {
        GLES30.glColorMask(red, green, blue, alpha);
        ci.cancel();
    }

    // Clear
    @Inject(method = "clearColor", at = @At("HEAD"), cancellable = true)
    private static void onClearColor(float red, float green, float blue, float alpha, CallbackInfo ci) {
        // Stored, applied on clear
        ci.cancel();
    }

    @Inject(method = "clearDepth", at = @At("HEAD"), cancellable = true)
    private static void onClearDepth(double depth, CallbackInfo ci) {
        GLES30.glClearDepthf((float) depth);
        ci.cancel();
    }

    @Inject(method = "clearStencil", at = @At("HEAD"), cancellable = true)
    private static void onClearStencil(int s, CallbackInfo ci) {
        GLES30.glClearStencil(s);
        ci.cancel();
    }

    // Mapping functions
    private static int mapCap(int cap) {
        return switch (cap) {
            case 0x0B44 -> GLES30.GL_CULL_FACE;           // GL_CULL_FACE
            case 0x0B71 -> GLES30.GL_DEPTH_TEST;          // GL_DEPTH_TEST
            case 0x0BE2 -> GLES30.GL_BLEND;               // GL_BLEND
            case 0x0B90 -> GLES30.GL_STENCIL_TEST;        // GL_STENCIL_TEST
            case 0x0C11 -> GLES30.GL_SCISSOR_TEST;        // GL_SCISSOR_TEST
            case 0x0B46 -> GLES30.GL_POLYGON_OFFSET_FILL; // GL_POLYGON_OFFSET_FILL
            case 0x0D50 -> GLES30.GL_SAMPLE_ALPHA_TO_COVERAGE; // GL_SAMPLE_ALPHA_TO_COVERAGE
            case 0x809E -> GLES30.GL_SAMPLE_COVERAGE;     // GL_SAMPLE_COVERAGE
            default -> -1; // Unknown cap, let original handle
        };
    }

    private static int mapBlendFactor(int factor) {
        return switch (factor) {
            case 0 -> GLES30.GL_ZERO;
            case 1 -> GLES30.GL_ONE;
            case 0x0300 -> GLES30.GL_SRC_COLOR;
            case 0x0301 -> GLES30.GL_ONE_MINUS_SRC_COLOR;
            case 0x0302 -> GLES30.GL_SRC_ALPHA;
            case 0x0303 -> GLES30.GL_ONE_MINUS_SRC_ALPHA;
            case 0x0304 -> GLES30.GL_DST_ALPHA;
            case 0x0305 -> GLES30.GL_ONE_MINUS_DST_ALPHA;
            case 0x0306 -> GLES30.GL_DST_COLOR;
            case 0x0307 -> GLES30.GL_ONE_MINUS_DST_COLOR;
            case 0x0308 -> GLES30.GL_SRC_ALPHA_SATURATE;
            default -> factor;
        };
    }

    private static int mapDepthFunc(int func) {
        return switch (func) {
            case 0x0200 -> GLES30.GL_NEVER;
            case 0x0201 -> GLES30.GL_LESS;
            case 0x0202 -> GLES30.GL_EQUAL;
            case 0x0203 -> GLES30.GL_LEQUAL;
            case 0x0204 -> GLES30.GL_GREATER;
            case 0x0205 -> GLES30.GL_NOTEQUAL;
            case 0x0206 -> GLES30.GL_GEQUAL;
            case 0x0207 -> GLES30.GL_ALWAYS;
            default -> GLES30.GL_LESS;
        };
    }

    private static int mapCullFace(int mode) {
        return switch (mode) {
            case 0x0404 -> GLES30.GL_FRONT;
            case 0x0405 -> GLES30.GL_BACK;
            case 0x0408 -> GLES30.GL_FRONT_AND_BACK;
            default -> GLES30.GL_BACK;
        };
    }

    private static int mapStencilFunc(int func) {
        return switch (func) {
            case 0x0200 -> GLES30.GL_NEVER;
            case 0x0201 -> GLES30.GL_LESS;
            case 0x0202 -> GLES30.GL_EQUAL;
            case 0x0203 -> GLES30.GL_LEQUAL;
            case 0x0204 -> GLES30.GL_GREATER;
            case 0x0205 -> GLES30.GL_NOTEQUAL;
            case 0x0206 -> GLES30.GL_GEQUAL;
            case 0x0207 -> GLES30.GL_ALWAYS;
            default -> GLES30.GL_ALWAYS;
        };
    }

    private static int mapStencilOp(int op) {
        return switch (op) {
            case 0 -> GLES30.GL_KEEP;
            case 0x1E00 -> GLES30.GL_ZERO;
            case 0x1E01 -> GLES30.GL_REPLACE;
            case 0x150A -> GLES30.GL_INCR;
            case 0x150B -> GLES30.GL_DECR;
            case 0x8507 -> GLES30.GL_INVERT;
            case 0x8508 -> GLES30.GL_INCR_WRAP;
            case 0x8509 -> GLES30.GL_DECR_WRAP;
            default -> GLES30.GL_KEEP;
        };
    }
