{"content":"package net.glesbridge.shim;

import org.lwjgl.gles.GLES30;
import org.lwjgl.gles.GLES31;
import org.lwjgl.gles.GLES32;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Compatibility shim for mods that call raw OpenGL (GL11/GL30) instead of RenderSystem.
 * This is a MINIMAL shim - only covers the most common calls.
 * Mods using raw GL are explicitly NOT fully supported - this is best-effort.
 */
public class GLESCompatShim {
    private static final Logger LOGGER = LoggerFactory.getLogger("GLES Bridge/Compat");

    // State to track if shim is active
    private static boolean shimActive = false;

    public static void enableShim() {
        if (!shimActive) {
            shimActive = true;
            LOGGER.info("GLES Compatibility Shim enabled - raw GL calls will be redirected to GLES");
        }
    }

    public static void disableShim() {
        shimActive = false;
        LOGGER.info("GLES Compatibility Shim disabled");
    }

    public static boolean isShimActive() {
        return shimActive;
    }

    // ===== GL11 =====

    public static void glEnable(int cap) {
        if (!shimActive) return;
        int glesCap = mapCap(cap);
        if (glesCap >= 0) GLES30.glEnable(glesCap);
        else LOGGER.debug("GL11 glEnable: unknown cap 0x{:X}", cap);
    }

    public static void glDisable(int cap) {
        if (!shimActive) return;
        int glesCap = mapCap(cap);
        if (glesCap >= 0) GLES30.glDisable(glesCap);
        else LOGGER.debug("GL11 glDisable: unknown cap 0x{:X}", cap);
    }

    public static void glViewport(int x, int y, int width, int height) {
        if (!shimActive) return;
        GLES30.glViewport(x, y, width, height);
    }

    public static void glClearColor(float red, float green, float blue, float alpha) {
        if (!shimActive) return;
        GLES30.glClearColor(red, green, blue, alpha);
    }

    public static void glClear(int mask) {
        if (!shimActive) return;
        GLES30.glClear(mapClearMask(mask));
    }

    public static void glColorMask(boolean red, boolean green, boolean blue, boolean alpha) {
        if (!shimActive) return;
        GLES30.glColorMask(red, green, blue, alpha);
    }

    public static void glDepthMask(boolean flag) {
        if (!shimActive) return;
        GLES30.glDepthMask(flag);
    }

    public static void glDepthFunc(int func) {
        if (!shimActive) return;
        GLES30.glDepthFunc(mapDepthFunc(func));
    }

    public static void glBlendFunc(int sfactor, int dfactor) {
        if (!shimActive) return;
        GLES30.glBlendFunc(mapBlendFactor(sfactor), mapBlendFactor(dfactor));
    }

    public static void glBlendFuncSeparate(int srcRGB, int dstRGB, int srcAlpha, int dstAlpha) {
        if (!shimActive) return;
        GLES30.glBlendFuncSeparate(mapBlendFactor(srcRGB), mapBlendFactor(dstRGB),
                                   mapBlendFactor(srcAlpha), mapBlendFactor(dstAlpha));
    }

    public static void glCullFace(int mode) {
        if (!shimActive) return;
        GLES30.glCullFace(mapCullFace(mode));
    }

    public static void glFrontFace(int mode) {
        if (!shimActive) return;
        GLES30.glFrontFace(mode == 0x0900 ? GLES30.GL_CCW : GLES30.GL_CW);
    }

    public static void glPolygonOffset(float factor, float units) {
        if (!shimActive) return;
        GLES30.glPolygonOffset(factor, units);
    }

    public static void glScissor(int x, int y, int width, int height) {
        if (!shimActive) return;
        GLES30.glScissor(x, y, width, height);
    }

