    // ===== Mapping functions =====

    private static int mapCap(int cap) {
        return switch (cap) {
            case 0x0B44 -> GLES30.GL_CULL_FACE;
            case 0x0B71 -> GLES30.GL_DEPTH_TEST;
            case 0x0BE2 -> GLES30.GL_BLEND;
            case 0x0B90 -> GLES30.GL_STENCIL_TEST;
            case 0x0C11 -> GLES30.GL_SCISSOR_TEST;
            case 0x0B46 -> GLES30.GL_POLYGON_OFFSET_FILL;
            case 0x0D50 -> GLES30.GL_SAMPLE_ALPHA_TO_COVERAGE;
            case 0x809E -> GLES30.GL_SAMPLE_COVERAGE;
            case 0x0D05 -> GLES30.GL_DITHER;
            default -> -1;
        };
    }

    private static int mapBlendFactor(int factor) {
        return switch (factor) {
            case 0 -> GLES30.GL_ZERO;
            case 1 -> GLES30.GL_ONE;
            case 0x0300 -> GLES30.GL_SRC_COLOR;
            case 0x0301 -> GLES30.GL_ONE_MINUS_SRC_COLOR;
            case 0x0302 -> GLES30.GL_SRC_ALPHA;
            case 0x0303 -> GLES30.GL_ONE_MINUS_SRC_ALPHA;
            case 0x0304 -> GLES30.GL_DST_ALPHA;
            case 0x0305 -> GLES30.GL_ONE_MINUS_DST_ALPHA;
            case 0x0306 -> GLES30.GL_DST_COLOR;
            case 0x0307 -> GLES30.GL_ONE_MINUS_DST_COLOR;
            case 0x0308 -> GLES30.GL_SRC_ALPHA_SATURATE;
            default -> factor;
        };
    }

    private static int mapDepthFunc(int func) {
        return switch (func) {
            case 0x0200 -> GLES30.GL_NEVER;
            case 0x0201 -> GLES30.GL_LESS;
            case 0x0202 -> GLES30.GL_EQUAL;
            case 0x0203 -> GLES30.GL_LEQUAL;
            case 0x0204 -> GLES30.GL_GREATER;
            case 0x0205 -> GLES30.GL_NOTEQUAL;
            case 0x0206 -> GLES30.GL_GEQUAL;
            case 0x0207 -> GLES30.GL_ALWAYS;
            default -> GLES30.GL_LESS;
        };
    }

    private static int mapCullFace(int mode) {
        return switch (mode) {
            case 0x0404 -> GLES30.GL_FRONT;
            case 0x0405 -> GLES30.GL_BACK;
            case 0x0408 -> GLES30.GL_FRONT_AND_BACK;
            default -> GLES30.GL_BACK;
        };
    }

    private static int mapDrawMode(int mode) {
        return switch (mode) {
            case 0x0000 -> GLES30.GL_POINTS;
            case 0x0001 -> GLES30.GL_LINES;
            case 0x0003 -> GLES30.GL_LINE_STRIP;
            case 0x0002 -> GLES30.GL_LINE_LOOP;
            case 0x0004 -> GLES30.GL_TRIANGLES;
            case 0x0005 -> GLES30.GL_TRIANGLE_STRIP;
            case 0x0006 -> GLES30.GL_TRIANGLE_FAN;
            default -> mode;
        };
    }

    private static int mapDrawType(int type) {
        return switch (type) {
            case 0x1400 -> GLES30.GL_UNSIGNED_BYTE;
            case 0x1401 -> GLES30.GL_UNSIGNED_SHORT;
            case 0x1405 -> GLES30.GL_UNSIGNED_INT;
            default -> type;
        };
    }

    private static int mapClearMask(int mask) {
        int result = 0;
        if ((mask & 0x00004000) != 0) result |= GLES30.GL_COLOR_BUFFER_BIT;   // GL_COLOR_BUFFER_BIT
        if ((mask & 0x00000100) != 0) result |= GLES30.GL_DEPTH_BUFFER_BIT;   // GL_DEPTH_BUFFER_BIT
        if ((mask & 0x00000400) != 0) result |= GLES30.GL_STENCIL_BUFFER_BIT; // GL_STENCIL_BUFFER_BIT
        return result;
    }

    private static int mapShaderType(int type) {
        return switch (type) {
            case 0x8B31 -> GLES30.GL_VERTEX_SHADER;
            case 0x8B30 -> GLES30.GL_FRAGMENT_SHADER;
            case 0x8DD9 -> GLES31.GL_GEOMETRY_SHADER;
            case 0x8E87 -> GLES31.GL_TESS_CONTROL_SHADER;
            case 0x8E88 -> GLES31.GL_TESS_EVALUATION_SHADER;
            case 0x91B9 -> GLES31.GL_COMPUTE_SHADER;
            default -> type;
        };
    }

    private static String convertGLSLtoESSL(String source) {
        String result = source;

        // Version directive
        if (!result.contains("#version")) {
            result = "#version 300 es\n" + result;
        } else {
            result = result.replaceAll("#version\\s+\\d+", "#version 300 es");
        }

        // Precision
        if (!result.contains("precision highp float")) {
            result = result.replaceFirst("#version 300 es", "#version 300 es\nprecision highp float;\nprecision highp int;");
        }

        // Replace deprecated
        result = result
            .replace("gl_FragColor", "fragColor")
            .replace("gl_FragData", "fragData")
            .replace("texture2D(", "texture(")
            .replace("textureCube(", "texture(")
            .replace("texture2DProj(", "textureProj(")
            .replace("textureCubeLod(", "textureLod(")
            .replace("attribute ", "in ")
            .replace("varying ", "out ");

        return result;
    }
