{"content":"package net.glesbridge;

import net.fabricmc.api.EnvType;
import net.fabricmc.api.Environment;
import net.glesbridge.shim.GLESCompatShim;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@Environment(EnvType.CLIENT)
public class GLESBridgeAccess {
    private static final Logger LOGGER = LoggerFactory.getLogger("GLES Bridge/Access");

    /**
     * Check if the GLES Bridge is active and the compatibility shim is available.
     * Other mods can call this to use the shim for raw GL calls.
     */
    public static boolean isBridgeActive() {
        return true;
    }

    /**
     * Enable the compatibility shim for raw GL calls from other mods.
     * Call this during mod initialization if you need GL compatibility.
     */
    public static void enableCompatShim() {
        GLESCompatShim.enableShim();
        LOGGER.info("GLES Bridge: Compatibility shim enabled for mod use");
    }

    /**
     * Get the compatibility shim instance.
     * Use this to make raw GL calls that will be redirected to GLES.
     */
    public static GLESCompatShim getCompatShim() {
        return new GLESCompatShim();
    }

    /**
     * Check if we're running on GLES (not desktop GL).
     */
    public static boolean isGLES() {
        return true;
    }

    /**
     * Get the GLES version string.
     */
    public static String getGLESVersion() {
        return org.lwjgl.gles.GLES30.glGetString(org.lwjgl.gles.GLES30.GL_VERSION);
    }
